//! Typed command results. Their TypeScript declarations are generated by tsify.
use fujimod_emulator_session::{
    card::CardState,
    contact_driver::{ControlInput, QueueState},
    history::Boundary,
};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use tsify::Tsify;

/// Guest time at a restored or exported point. Decimal strings keep full u64 range.
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct Point {
    pub tick: String,
    pub instructions: Vec<String>,
}
impl Point {
    pub fn new(tick: u64, instructions: &[u64]) -> Self {
        Self {
            tick: tick.to_string(),
            instructions: instructions.iter().map(u64::to_string).collect(),
        }
    }
}
impl From<Boundary> for Point {
    fn from(value: Boundary) -> Self {
        Self::new(value.tick, &value.instructions)
    }
}
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct Checkpoint {
    pub id: String,
    pub tick: String,
    pub instructions: Vec<String>,
    /// Checkpoint IDs still retained after this one, oldest first.
    pub retained_ids: Vec<String>,
}
/// Host-visible controls, card and power after a state-changing command.
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct SessionState {
    pub inputs: Vec<ControlInput>,
    #[tsify(type = "Record<string, string>")]
    pub positions: BTreeMap<String, String>,
    pub input_queue: Option<QueueState>,
    pub card: CardState,
    pub powered_on: bool,
}
/// Portable committed storage of an owned camera.
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct SavedMedia {
    #[serde(with = "serde_bytes")]
    #[tsify(type = "Uint8Array")]
    pub durable: Vec<u8>,
    #[tsify(type = "Record<string, string>")]
    pub positions: BTreeMap<String, String>,
    pub powered_on: bool,
}
/// A complete running session, loadable by `Camera.fromSnapshot`.
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct SessionSnapshot {
    #[serde(with = "serde_bytes")]
    #[tsify(type = "Uint8Array")]
    pub snapshot: Vec<u8>,
    pub tick: String,
    pub instructions: Vec<String>,
}
/// Inputs since the last checkpoint, replayable by `replay`.
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct InputLog {
    #[serde(with = "serde_bytes")]
    #[tsify(type = "Uint8Array")]
    pub log: Vec<u8>,
    pub entries: usize,
}
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct Fingerprint {
    pub sha256: String,
}
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct Preview {
    pub ticks_per_second: String,
    pub frames: u64,
    /// The preview clock's complete saved device state.
    #[tsify(type = "Record<string, unknown>")]
    pub state: serde_json::Value,
}
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct DeviceWorkers {
    /// Stopped host preference; Exact execution always computes inline.
    pub count: usize,
    pub effective: usize,
}
#[derive(Serialize, Tsify)]
#[serde(rename_all = "camelCase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct Profile {
    pub ticks: u64,
    pub instructions: Vec<u64>,
    #[tsify(type = "unknown[]")]
    pub pc_entries: Vec<serde_json::Value>,
    pub failed: bool,
}
/// Board diagnostics and the newest restorable snapshot, when one encodes.
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct ErrorReport {
    #[tsify(type = "Record<string, unknown>")]
    pub report: serde_json::Value,
    #[serde(with = "serde_bytes")]
    #[tsify(type = "Uint8Array | null")]
    pub snapshot: Option<Vec<u8>>,
}
#[derive(Serialize, Tsify)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct DeviceStates {
    #[tsify(type = "unknown[]")]
    pub states: serde_json::Value,
}
/// USB cable and endpoint bus progress.
#[derive(Deserialize, Serialize, Tsify)]
#[serde(deny_unknown_fields)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct UsbStatus {
    pub connected: bool,
    pub endpoint: fujimod_emulator_parts_io::usb_endpoint::BusStatus,
}
/// Touch phases accepted by `touch`.
#[derive(Clone, Copy, Deserialize, Tsify)]
#[serde(rename_all = "lowercase")]
#[tsify(hashmap_as_object, missing_as_null)]
pub enum TouchPhase {
    Press,
    Drag,
    Release,
    Tap,
}
impl TouchPhase {
    pub fn name(self) -> &'static str {
        match self {
            Self::Press => "press",
            Self::Drag => "drag",
            Self::Release => "release",
            Self::Tap => "tap",
        }
    }
}
/// A card file inside one packed upload, in upload order.
#[derive(Deserialize, Tsify)]
#[serde(deny_unknown_fields)]
#[tsify(hashmap_as_object, missing_as_null)]
pub struct CardFile {
    pub path: String,
    pub offset: usize,
    pub length: usize,
}
